# Aggregate SQL uses only bound values; scope clauses are built by the server.
QUERIES = {
    "previous_store": "SELECT store_id,SUM(amount) sales FROM dw_fact_orders WHERE ordered_at BETWEEN ? AND ?{scope_plain} GROUP BY store_id",
    "by_store": "SELECT s.id storeId,s.name storeName,SUM(o.amount) sales,COUNT(*) orders,COUNT(DISTINCT o.customer_id) customers FROM dw_fact_orders o JOIN stores s ON s.id=o.store_id WHERE o.ordered_at BETWEEN ? AND ?{scope_o} GROUP BY s.id ORDER BY sales DESC,s.id",
    "by_channel": "SELECT channel,SUM(amount) sales,COUNT(*) orders,COUNT(DISTINCT customer_id) customers FROM dw_fact_orders WHERE ordered_at BETWEEN ? AND ?{scope_plain} GROUP BY channel ORDER BY sales DESC",
    "by_category": "SELECT p.category,SUM(i.quantity*i.unit_price) sales,COUNT(DISTINCT o.id) orders,SUM(i.quantity) quantity FROM order_items i JOIN dw_fact_orders o ON o.id=i.order_id JOIN products p ON p.id=i.product_id WHERE o.ordered_at BETWEEN ? AND ?{scope_o} GROUP BY p.category ORDER BY sales DESC",
    "monthly_store": "SELECT substr(o.ordered_at,1,7) month,s.id storeId,s.name storeName,SUM(o.amount) sales,COUNT(*) orders FROM dw_fact_orders o JOIN stores s ON s.id=o.store_id WHERE o.ordered_at BETWEEN ? AND ?{scope_o} GROUP BY month,s.id ORDER BY month,s.id",
    "monthly_category": "SELECT substr(o.ordered_at,1,7) month,p.category,SUM(i.quantity*i.unit_price) sales FROM order_items i JOIN dw_fact_orders o ON o.id=i.order_id JOIN products p ON p.id=i.product_id WHERE o.ordered_at BETWEEN ? AND ?{scope_o} GROUP BY month,p.category ORDER BY month,p.category",
    "by_grade": "SELECT c.grade,SUM(o.amount) sales,COUNT(*) orders,COUNT(DISTINCT c.id) customers FROM dw_fact_orders o JOIN customers c ON c.id=o.customer_id WHERE o.ordered_at BETWEEN ? AND ?{scope_o} GROUP BY c.grade ORDER BY sales DESC",
    "budget_store": "SELECT s.id storeId,s.name storeName,SUM(b.planned) planned,SUM(b.spent) spent,SUM(b.sales_target) salesTarget FROM budget_daily b JOIN stores s ON s.id=b.store_id WHERE b.date BETWEEN ? AND ?{scope_b} GROUP BY s.id",
    "departments": "SELECT department,SUM(planned) planned,SUM(spent) spent,SUM(sales_target) salesTarget FROM budget_daily WHERE date BETWEEN ? AND ?{scope_plain} GROUP BY department",
    "campaigns": "SELECT c.id,c.name,c.channel,c.start_date startDate,c.end_date endDate,COUNT(DISTINCT t.id) target,COUNT(DISTINCT CASE WHEN o.id IS NOT NULL THEN t.id END) converted,COALESCE(SUM(o.amount),0) revenue FROM campaigns c JOIN campaign_targets t ON t.campaign_id=c.id LEFT JOIN dw_fact_orders o ON o.campaign_target_id=t.id AND o.ordered_at BETWEEN ? AND ? WHERE t.targeted_at BETWEEN ? AND ?{scope_t} GROUP BY c.id ORDER BY revenue DESC",
    "campaign_cost": "SELECT COALESCE(SUM(planned),0) planned,COALESCE(SUM(spent),0) spent FROM campaign_spend WHERE campaign_id=? AND date BETWEEN ? AND ?{scope_plain}",
    "app_store": "SELECT s.id storeId,s.name storeName,COUNT(*) sessions,COUNT(DISTINCT a.customer_id) users,COUNT(a.order_id) purchases,ROUND(AVG(a.duration_seconds)) averageDuration FROM app_sessions a JOIN stores s ON s.id=a.store_id WHERE a.session_date BETWEEN ? AND ?{scope_a} GROUP BY s.id",
}
